#pragma material(BlendMode = Translucent, ShadingModel = Unlit, Backend = Graph)

/// Multiplied on top
/// @group Glow|Look
uniform float4 Tint = float4(1.0, 0.5, 0.25, 1.0);

/// @group Glow|Look
/// @slider 0.0 4.0
uniform float Intensity = 0.7;

/// @name Base Offset
uniform float2 Offset = float2(0.25, 0.5);

/// @sort 90
uniform float Late = 1.0;

export void M_RtUniforms(inout material m)
{
    m.EmissiveColor = Tint.xyz * Intensity + float3(Offset, Late);
    m.Opacity = Tint.w;
}

#pragma layout(Node, Var = Late, X = 506, Y = 152)
#pragma layout(Node, Var = Offset, X = 0, Y = -586)
#pragma layout(Node, Var = Intensity, X = 488, Y = -620)
#pragma layout(Node, Var = Tint, X = 398, Y = -288)
